"""Split a command line into argument tokens."""


def split_args(line):
    """Split `line` into arguments, honoring double quotes."""
    parts = []
    current = ""
    in_quotes = False
    has_token = False
    for ch in line:
        if in_quotes:
            if ch == '"':
                in_quotes = False
            else:
                current += ch
            has_token = True
        elif ch == '"':
            in_quotes = True
            has_token = True
        elif ch == " ":
            if has_token:
                parts.append(current)
            current = ""
            has_token = False
        else:
            current += ch
            has_token = True
    if has_token:
        parts.append(current)
    return parts
